function roundedRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);c.fill();}
function drawRoads(){ctx.fillStyle='#192327';ctx.fillRect(0,0,WORLD,WORLD);for(let n=0;n<7;n++){const q=n*TILE;ctx.fillStyle='#353b3a';ctx.fillRect(q,0,ROAD,WORLD);ctx.fillRect(0,q,WORLD,ROAD);ctx.fillStyle='#c2b97c';for(let v=8;v<WORLD;v+=38){ctx.fillRect(q+ROAD/2-2,v,4,19);ctx.fillRect(v,q+ROAD/2-2,19,4);}ctx.fillStyle='#9a9e85';ctx.fillRect(q+4,0,3,WORLD);ctx.fillRect(0,q+4,WORLD,3);ctx.fillRect(q+ROAD-7,0,3,WORLD);ctx.fillRect(0,q+ROAD-7,WORLD,3);for(let v=20;v<WORLD;v+=160){ctx.fillStyle='#ddd6aa';ctx.fillRect(q+12,v,10,3);ctx.fillRect(v,q+12,3,10);}}
  // Neighborhood label placards
  ctx.font='bold 11px monospace';for(let y=0;y<7;y++)for(let x=0;x<7;x++){ctx.fillStyle='#a1aca255';ctx.fillText(['OLD TOWN','VICE POINT','DOCKSIDE','MIDTOWN','PALM PARK','EAST END','SUNSET'][((x+y*2)%7)],x*TILE+ROAD+22,y*TILE+ROAD+18);}}
function drawBuildings(){for(const b of buildings){ctx.fillStyle='#101719';roundedRect(ctx,b.x+7,b.y+9,b.w,b.h,7);const palette=['#59615a','#515f63','#75634e','#626957','#6d5351','#4d5b6b','#6f705b'];ctx.fillStyle=palette[b.type];roundedRect(ctx,b.x,b.y,b.w,b.h,7);ctx.fillStyle='#849083';ctx.fillRect(b.x+7,b.y+8,b.w-14,4);ctx.fillStyle='#202c30';ctx.fillRect(b.x+12,b.y+24,b.w-24,b.h-38);ctx.fillStyle=['#a34e43','#d2a648','#54a3a2','#9e6852','#d49a53','#547c9a','#bd594d'][b.type];ctx.fillRect(b.x+15,b.y+14,b.w-30,18);ctx.fillStyle='#e7e1c4';ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.fillText(b.name,b.x+b.w/2,b.y+28);ctx.textAlign='left';for(let wy=b.y+50;wy<b.y+b.h-15;wy+=28)for(let wx=b.x+20;wx<b.x+b.w-15;wx+=34){ctx.fillStyle=(Math.floor(wx+wy)%3===0)?'#d8c57b':'#536b70';ctx.fillRect(wx,wy,15,12);ctx.fillStyle='#293538';ctx.fillRect(wx+6,wy,2,12);}ctx.fillStyle='#252c2a';ctx.fillRect(b.x+b.w/2-14,b.y+b.h-23,28,23);}}
function drawTree(t){ctx.fillStyle='#101917';ctx.beginPath();ctx.ellipse(t.x+3,t.y+5,16,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#46684b';ctx.beginPath();ctx.arc(t.x,t.y,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#678151';ctx.beginPath();ctx.arc(t.x-4,t.y-4,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#8c7654';ctx.fillRect(t.x-2,t.y+9,4,7);}
function drawCar(c){ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.dir);ctx.fillStyle='#111';roundedRect(ctx,-18,-10,38,21,5);ctx.fillStyle=c.police?'#d8d8ca':c.color;roundedRect(ctx,-19,-9,38,18,4);ctx.fillStyle='#31484c';ctx.fillRect(-6,-7,14,14);ctx.fillStyle='#e7d98a';ctx.fillRect(15,-6,3,4);ctx.fillRect(15,3,3,4);ctx.fillStyle='#20272a';ctx.fillRect(-12,-11,8,3);ctx.fillRect(8,-11,8,3);ctx.fillRect(-12,8,8,3);ctx.fillRect(8,8,8,3);if(c.police){ctx.fillStyle='#d7413e';ctx.fillRect(-3,-11,6,3);ctx.fillStyle='#3285bb';ctx.fillRect(2,-11,4,3);}ctx.restore();}
function drawPerson(){ctx.save();ctx.translate(player.x,player.y);ctx.fillStyle='#15191a';ctx.beginPath();ctx.ellipse(0,4,8,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#dfb54e';ctx.fillRect(-5,-4,10,10);ctx.fillStyle='#d4a778';ctx.beginPath();ctx.arc(0,-7,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#30373a';ctx.fillRect(-5,-12,10,3);ctx.restore();}
function drawObjective(o,color,label){const pulse=1+Math.sin(performance.now()/220)*.13;ctx.save();ctx.translate(o.x,o.y);ctx.strokeStyle=color;ctx.lineWidth=3;ctx.globalAlpha=.85;ctx.beginPath();ctx.arc(0,0,22*pulse,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=.3;ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,0,19,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#fff';ctx.font='bold 10px monospace';ctx.textAlign='center';ctx.fillText(label,0,-29);ctx.restore();}
function drawMinimap(){const mw=150,mh=112,x=W-165,y=15,scale=mw/WORLD;ctx.fillStyle='#0b1014dd';ctx.fillRect(x-5,y-5,mw+10,mh+10);ctx.fillStyle='#536056';for(const b of buildings)ctx.fillRect(x+b.x*scale,y+b.y*scale,b.w*scale,b.h*scale);ctx.strokeStyle='#cbbd75';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+Math.floor(player.x/TILE)*TILE*scale,y);ctx.lineTo(x+Math.floor(player.x/TILE)*TILE*scale,y+mh);ctx.moveTo(x,y+Math.floor(player.y/TILE)*TILE*scale);ctx.lineTo(x+mw,y+Math.floor(player.y/TILE)*TILE*scale);ctx.stroke();ctx.fillStyle='#59d988';ctx.fillRect(x+pickup.x*scale-2,y+pickup.y*scale-2,5,5);ctx.fillStyle='#f0ce55';ctx.fillRect(x+drop.x*scale-2,y+drop.y*scale-2,5,5);ctx.fillStyle='#ef5550';for(const c of cops)ctx.fillRect(x+c.x*scale-2,y+c.y*scale-2,4,4);ctx.fillStyle='#f2e8c5';ctx.beginPath();ctx.arc(x+player.x*scale,y+player.y*scale,3,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c6c6a5';ctx.lineWidth=1;ctx.strokeRect(x-.5,y-.5,mw+1,mh+1);ctx.font='9px monospace';ctx.fillStyle='#d9dfc2';ctx.textAlign='left';ctx.fillText('VICE GRID',x+3,y+mh+13);}
function render(){ctx.clearRect(0,0,W,H);ctx.save();ctx.translate(-camera.x,-camera.y);drawRoads();drawBuildings();trees.forEach(drawTree);for(const c of cars)drawCar(c);for(const c of cops)drawCar({...c,color:'#e6e5d6',police:true});drawObjective(missionStage==='pickup'?pickup:drop,missionStage==='pickup'?'#61e08a':'#f3d252',missionStage==='pickup'?'PAKET':'CILJ');if(!player.inCar)drawPerson();ctx.restore();drawMinimap();
  // compact speedometer and district overlay
  if(player.inCar){ctx.fillStyle='#101719dd';roundedRect(ctx,18,H-58,154,40,5);ctx.fillStyle='#d9dcbe';ctx.font='bold 12px monospace';ctx.fillText('BRZINA',29,H-40);ctx.fillStyle='#d8d994';ctx.font='bold 20px monospace';ctx.fillText(String(Math.round(Math.abs(player.car.speed)*24)).padStart(3,'0')+' km/h',29,H-21);}
  if(weather==='RAIN'){ctx.strokeStyle='#a6cee944';ctx.lineWidth=1;for(let i=0;i<75;i++){const x=(i*137+performance.now()*.32)%W,y=(i*83+performance.now()*.72)%H;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-6,y+14);ctx.stroke();}}
  const hour=Math.floor(gameTime/60)%24;if(hour>=19||hour<6){ctx.fillStyle='#09101a55';ctx.fillRect(0,0,W,H);}
}
let last=performance.now();function loop(now){const dt=Math.min((now-last)/1000,.04);last=now;update(dt);render();requestAnimationFrame(loop);}setTask();updateHud();requestAnimationFrame(loop);
})();
</script>
</body>
</html>

