(()=>{'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height,TILE=320,ROAD=92,WORLD=TILE*7;
const ui={cash:document.getElementById('cash'),time:document.getElementById('time'),weather:document.getElementById('weather'),wanted:document.getElementById('wanted'),task:document.getElementById('task'),toast:document.getElementById('toast'),pause:document.getElementById('pause')};
const keys=new Set,rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
let paused=false,toastTimer=0,gameTime=480,cash=250,wanted=0,weather='SUNNY',weatherIcon='☀️',weatherTick=0,delivery=0,missionStage='pickup',collisions=0;
const player={x:137,y:140,dir:0,speed:0,inCar:false,car:null},camera={x:0,y:0},colors=['#c85b46','#d3b94e','#477e9a','#738b53','#bd7346','#9a6386','#d1d1b4'],buildings=[],cars=[],trees=[],cops=[];
for(let gy=0;gy<7;gy++)for(let gx=0;gx<7;gx++){const bx=gx*TILE+ROAD+16,by=gy*TILE+ROAD+16,bw=TILE-ROAD-32,bh=TILE-ROAD-32,type=(gx*3+gy*5)%7;buildings.push({x:bx,y:by,w:bw,h:bh,type,name:['HOTEL','ARCADE','MARKET','GARAGE','CLUB','OFFICE','DINER'][type]});trees.push({x:gx*TILE+ROAD+8,y:gy*TILE+ROAD+8},{x:gx*TILE+TILE-10,y:gy*TILE+ROAD+8},{x:gx*TILE+ROAD+8,y:gy*TILE+TILE-10},{x:gx*TILE+TILE-10,y:gy*TILE+TILE-10});if(Math.random()<.78)for(let j=0;j<2;j++){const h=Math.random()<.5,lane=h?gy*TILE+rand(20,ROAD-20):gx*TILE+rand(20,ROAD-20);cars.push({x:h?gx*TILE+rand(ROAD+12,TILE-50):lane,y:h?lane:gy*TILE+rand(ROAD+12,TILE-50),dir:h?0:Math.PI/2,color:colors[Math.floor(Math.random()*colors.length)],speed:0,parked:true,police:false});}}
const spots=[{x:151,y:145},{x:WORLD-155,y:155},{x:WORLD-155,y:WORLD-155},{x:160,y:WORLD-155},{x:WORLD/2,y:WORLD/2}];let pickup={...spots[0]},drop={...spots[1]};
function toast(m){ui.toast.textContent=m;ui.toast.style.display='block';toastTimer=2.2}function setTask(){ui.task.textContent=missionStage==='pickup'?'Преузми пакет на зеленој ознаци. Избегавај полицију!':'Испоручи пакет на златној ознаци · Награда $'+(120+delivery*25)+'.'}function updateHud(){ui.cash.textContent='$ '+cash;ui.time.textContent=String(Math.floor(gameTime/60)%24).padStart(2,'0')+':'+String(Math.floor(gameTime)%60).padStart(2,'0');ui.weather.textContent=weatherIcon+' '+weather;ui.wanted.textContent='POLICE '+('★'.repeat(wanted))+('☆'.repeat(5-wanted))}
function solidAt(x,y,r=10){return x<r||y<r||x>WORLD-r||y>WORLD-r||buildings.some(b=>x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)}function move(e,dx,dy,r=10){const nx=e.x+dx;if(!solidAt(nx,e.y,r))e.x=nx;else if(e===player&&e.inCar){e.speed*=-.28;collisions++}const ny=e.y+dy;if(!solidAt(e.x,ny,r))e.y=ny;else if(e===player&&e.inCar)e.speed*=-.28;e.x=clamp(e.x,r,WORLD-r);e.y=clamp(e.y,r,WORLD-r)}
function nearestCar(){return cars.filter(c=>!c.police&&dist(c,player)<54).sort((a,b)=>dist(a,player)-dist(b,player))[0]}function interact(){if(player.inCar){player.inCar=false;player.car.occupied=false;player.x+=Math.cos(player.dir+Math.PI/2)*25;player.y+=Math.sin(player.dir+Math.PI/2)*25;player.speed=0;toast('Izašao si iz vozila.');return}const c=nearestCar();if(c){player.inCar=true;player.car=c;c.occupied=true;player.dir=c.dir;toast('Ukradeno vozilo! Pazi na patrolu.');wanted=Math.min(5,wanted+1);c.speed=0;return}if(dist(player,missionStage==='pickup'?pickup:drop)<40)objective()}
function objective(){if(missionStage==='pickup'){missionStage='drop';toast('ПАКЕТ ПРЕУЗЕТ — испоручи га!')}else{const reward=120+delivery*25;cash+=reward;delivery++;missionStage='pickup';pickup={...spots[(delivery+1)%spots.length]};drop={...spots[(delivery+2)%spots.length]};if(dist(pickup,drop)<100)drop={...spots[(delivery+3)%spots.length]};toast('Испорука успешна! +$'+reward);wanted=Math.max(0,wanted-1)}setTask();updateHud()}
function reset(){cash=250;wanted=0;delivery=0;missionStage='pickup';player.x=137;player.y=140;player.dir=0;player.speed=0;player.inCar=false;player.car=null;gameTime=480;pickup={...spots[0]};drop={...spots[1]};cops.length=0;setTask();updateHud();toast('Нова смена почиње!')}
function action(k){if(k==='e'||k==='enter'){interact();return}if(k==='p'||k==='escape'){paused=!paused;ui.pause.style.display=paused?'grid':'none';return}if(k==='r')reset()}window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(!keys.has(k))action(k);keys.add(k)});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());document.querySelectorAll('#touch [data-key]').forEach(b=>{const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(k);b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys.delete(k)))});document.querySelector('[data-action="interact"]').addEventListener('pointerdown',e=>{e.preventDefault();interact()});const down=(...n)=>n.some(k=>keys.has(k));
function newCop(){const a=rand(0,Math.PI*2),r=rand(420,650);return{x:clamp(player.x+Math.cos(a)*r,40,WORLD-40),y:clamp(player.y+Math.sin(a)*r,40,WORLD-40),dir:0,speed:0,police:true}}function update(dt){if(paused)return;gameTime=(gameTime+dt*2.2)%(24*60);weatherTick+=dt;if(weatherTick>95){weatherTick=0;const rain=Math.random()<.38;weather=rain?'RAIN':'SUNNY';weatherIcon=rain?'🌧️':'☀️';toast(rain?'Kiša pada — klizavi putevi!':'Oblačno se razvedrilo.')}if(toastTimer>0&&(toastTimer-=dt)<=0)ui.toast.style.display='none';const up=down('w','arrowup'),dn=down('s','arrowdown'),lf=down('a','arrowleft'),rt=down('d','arrowright'),hand=down(' ');
if(player.inCar){const c=player.car,acc=weather==='RAIN'?.105:.14;if(up)c.speed=Math.min(c.speed+acc*dt*60,5.4);if(dn)c.speed=Math.max(c.speed-.19*dt*60,-2.4);c.speed*=Math.pow(hand?.91:.985,dt*60);const steer=(rt?1:0)-(lf?1:0);c.dir+=steer*clamp(Math.abs(c.speed)/3,0,1)*.045*dt*60*(c.speed<0?-1:1);player.dir=c.dir;move(c,Math.cos(c.dir)*c.speed*dt*60,Math.sin(c.dir)*c.speed*dt*60,15);player.x=c.x;player.y=c.y;if(Math.abs(c.speed)>.7)for(const o of cars)if(o!==c&&!o.police&&dist(c,o)<27){c.speed*=-.45;o.speed=0;if(++collisions%3===0)wanted=Math.min(5,wanted+1);toast('Sudar!');break}}
else{let dx=(rt?1:0)-(lf?1:0),dy=(dn?1:0)-(up?1:0);if(dx||dy){const l=Math.hypot(dx,dy);dx/=l;dy/=l;player.dir=Math.atan2(dy,dx);move(player,dx*2.1*dt*60,dy*2.1*dt*60,9)}}
if(wanted){while(cops.length<wanted)cops.push(newCop());for(const c of cops){const d=dist(c,player),a=Math.atan2(player.y-c.y,player.x-c.x);c.dir=a;c.speed=d>28?1.15+wanted*.22:0;move(c,Math.cos(a)*c.speed*dt*60,Math.sin(a)*c.speed*dt*60,14);if(d<25){cash=Math.max(0,cash-40);wanted=Math.max(0,wanted-1);c.x=clamp(c.x-Math.cos(a)*100,20,WORLD-20);c.y=clamp(c.y-Math.sin(a)*100,20,WORLD-20);if(player.inCar)player.car.speed*=.3;toast('Полиција те је зауставила: -$40')}}}
if(dist(player,missionStage==='pickup'?pickup:drop)<27)objective();camera.x=clamp(player.x-W/2,0,WORLD-W);camera.y=clamp(player.y-H/2,0,WORLD-H);updateHud()}

function rr(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);c.fill()}function roads(){ctx.fillStyle='#192327';ctx.fillRect(0,0,WORLD,WORLD);for(let n=0;n<7;n++){const q=n*TILE;ctx.fillStyle='#353b3a';ctx.fillRect(q,0,ROAD,WORLD);ctx.fillRect(0,q,WORLD,ROAD);ctx.fillStyle='#c2b97c';for(let v=8;v<WORLD;v+=38){ctx.fillRect(q+ROAD/2-2,v,4,19);ctx.fillRect(v,q+ROAD/2-2,19,4)}ctx.fillStyle='#9a9e85';ctx.fillRect(q+4,0,3,WORLD);ctx.fillRect(0,q+4,WORLD,3);ctx.fillRect(q+ROAD-7,0,3,WORLD);ctx.fillRect(0,q+ROAD-7,WORLD,3);for(let v=20;v<WORLD;v+=160){ctx.fillStyle='#ddd6aa';ctx.fillRect(q+12,v,10,3);ctx.fillRect(v,q+12,3,10)}}ctx.font='bold 11px monospace';for(let y=0;y<7;y++)for(let x=0;x<7;x++){ctx.fillStyle='#a1aca255';ctx.fillText(['OLD TOWN','VICE POINT','DOCKSIDE','MIDTOWN','PALM PARK','EAST END','SUNSET'][(x+y*2)%7],x*TILE+ROAD+22,y*TILE+ROAD+18)}}
function drawBuildings(){const palette=['#59615a','#515f63','#75634e','#626957','#6d5351','#4d5b6b','#6f705b'],signs=['#a34e43','#d2a648','#54a3a2','#9e6852','#d49a53','#547c9a','#bd594d'];for(const b of buildings){ctx.fillStyle='#101719';rr(ctx,b.x+7,b.y+9,b.w,b.h,7);ctx.fillStyle=palette[b.type];rr(ctx,b.x,b.y,b.w,b.h,7);ctx.fillStyle='#849083';ctx.fillRect(b.x+7,b.y+8,b.w-14,4);ctx.fillStyle='#202c30';ctx.fillRect(b.x+12,b.y+24,b.w-24,b.h-38);ctx.fillStyle=signs[b.type];ctx.fillRect(b.x+15,b.y+14,b.w-30,18);ctx.fillStyle='#e7e1c4';ctx.font='bold 12px monospace';ctx.textAlign='center';ctx.fillText(b.name,b.x+b.w/2,b.y+28);ctx.textAlign='left';for(let wy=b.y+50;wy<b.y+b.h-15;wy+=28)for(let wx=b.x+20;wx<b.x+b.w-15;wx+=34){ctx.fillStyle=(Math.floor(wx+wy)%3===0)?'#d8c57b':'#536b70';ctx.fillRect(wx,wy,15,12);ctx.fillStyle='#293538';ctx.fillRect(wx+6,wy,2,12)}ctx.fillStyle='#252c2a';ctx.fillRect(b.x+b.w/2-14,b.y+b.h-23,28,23)}}
function tree(t){ctx.fillStyle='#101917';ctx.beginPath();ctx.ellipse(t.x+3,t.y+5,16,12,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#46684b';ctx.beginPath();ctx.arc(t.x,t.y,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#678151';ctx.beginPath();ctx.arc(t.x-4,t.y-4,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#8c7654';ctx.fillRect(t.x-2,t.y+9,4,7)}function carDraw(c){ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.dir);ctx.fillStyle='#111';rr(ctx,-18,-10,38,21,5);ctx.fillStyle=c.police?'#d8d8ca':c.color;rr(ctx,-19,-9,38,18,4);ctx.fillStyle='#31484c';ctx.fillRect(-6,-7,14,14);ctx.fillStyle='#e7d98a';ctx.fillRect(15,-6,3,4);ctx.fillRect(15,3,3,4);ctx.fillStyle='#20272a';ctx.fillRect(-12,-11,8,3);ctx.fillRect(8,-11,8,3);ctx.fillRect(-12,8,8,3);ctx.fillRect(8,8,8,3);if(c.police){ctx.fillStyle='#d7413e';ctx.fillRect(-3,-11,6,3);ctx.fillStyle='#3285bb';ctx.fillRect(2,-11,4,3)}ctx.restore()}
function person(){ctx.save();ctx.translate(player.x,player.y);ctx.fillStyle='#15191a';ctx.beginPath();ctx.ellipse(0,4,8,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#dfb54e';ctx.fillRect(-5,-4,10,10);ctx.fillStyle='#d4a778';ctx.beginPath();ctx.arc(0,-7,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#30373a';ctx.fillRect(-5,-12,10,3);ctx.restore()}function marker(o,color,label){ctx.save();ctx.translate(o.x,o.y);ctx.strokeStyle=color;ctx.lineWidth=3;ctx.globalAlpha=.85;ctx.beginPath();ctx.arc(0,0,22*(1+Math.sin(performance.now()/220)*.13),0,Math.PI*2);ctx.stroke();ctx.globalAlpha=.3;ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,0,19,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#fff';ctx.font='bold 10px monospace';ctx.textAlign='center';ctx.fillText(label,0,-29);ctx.restore()}
function minimap(){const mw=150,mh=112,x=W-165,y=15,s=mw/WORLD;ctx.fillStyle='#0b1014dd';ctx.fillRect(x-5,y-5,mw+10,mh+10);ctx.fillStyle='#536056';for(const b of buildings)ctx.fillRect(x+b.x*s,y+b.y*s,b.w*s,b.h*s);ctx.strokeStyle='#cbbd75';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+Math.floor(player.x/TILE)*TILE*s,y);ctx.lineTo(x+Math.floor(player.x/TILE)*TILE*s,y+mh);ctx.moveTo(x,y+Math.floor(player.y/TILE)*TILE*s);ctx.lineTo(x+mw,y+Math.floor(player.y/TILE)*TILE*s);ctx.stroke();ctx.fillStyle='#59d988';ctx.fillRect(x+pickup.x*s-2,y+pickup.y*s-2,5,5);ctx.fillStyle='#f0ce55';ctx.fillRect(x+drop.x*s-2,y+drop.y*s-2,5,5);ctx.fillStyle='#ef5550';for(const c of cops)ctx.fillRect(x+c.x*s-2,y+c.y*s-2,4,4);ctx.fillStyle='#f2e8c5';ctx.beginPath();ctx.arc(x+player.x*s,y+player.y*s,3,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c6c6a5';ctx.lineWidth=1;ctx.strokeRect(x-.5,y-.5,mw+1,mh+1);ctx.font='9px monospace';ctx.fillStyle='#d9dfc2';ctx.textAlign='left';ctx.fillText('VICE GRID',x+3,y+mh+13)}
function render(){ctx.clearRect(0,0,W,H);ctx.save();ctx.translate(-camera.x,-camera.y);roads();drawBuildings();trees.forEach(tree);cars.forEach(carDraw);cops.forEach(c=>carDraw({...c,color:'#e6e5d6',police:true}));marker(missionStage==='pickup'?pickup:drop,missionStage==='pickup'?'#61e08a':'#f3d252',missionStage==='pickup'?'PAKET':'CILJ');if(!player.inCar)person();ctx.restore();minimap();if(player.inCar){ctx.fillStyle='#101719dd';rr(ctx,18,H-58,154,40,5);ctx.fillStyle='#d9dcbe';ctx.font='bold 12px monospace';ctx.fillText('BRZINA',29,H-40);ctx.fillStyle='#d8d994';ctx.font='bold 20px monospace';ctx.fillText(String(Math.round(Math.abs(player.car.speed)*24)).padStart(3,'0')+' km/h',29,H-21)}if(weather==='RAIN'){ctx.strokeStyle='#a6cee944';ctx.lineWidth=1;for(let i=0;i<75;i++){let x=(i*137+performance.now()*.32)%W,y=(i*83+performance.now()*.72)%H;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-6,y+14);ctx.stroke()}}const h=Math.floor(gameTime/60)%24;if(h>=19||h<6){ctx.fillStyle='#09101a55';ctx.fillRect(0,0,W,H)}}
let last=performance.now();function loop(now){const dt=Math.min((now-last)/1000,.04);last=now;update(dt);render();requestAnimationFrame(loop)}setTask();updateHud();requestAnimationFrame(loop);
})();
