(()=>{'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height,TILE=320,ROAD=92,WORLD=TILE*7,ui={cash:document.getElementById('cash'),time:document.getElementById('time'),weather:document.getElementById('weather'),wanted:document.getElementById('wanted'),task:document.getElementById('task'),toast:document.getElementById('toast'),pause:document.getElementById('pause')};
const keys=new Set,rand=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);let paused=false,toastTimer=0,gameTime=480,cash=250,wanted=0,weather='SUNNY',weatherIcon='☀️',weatherTick=0,delivery=0,missionStage='pickup',collisions=0;
