for(let gy=0;gy<7;gy++)for(let gx=0;gx<7;gx++){const bx=gx*TILE+ROAD+16,by=gy*TILE+ROAD+16,bw=TILE-ROAD-32,bh=TILE-ROAD-32,type=(gx*3+gy*5)%7;buildings.push({x:bx,y:by,w:bw,h:bh,type,name:['HOTEL','ARCADE','MARKET','GARAGE','CLUB','OFFICE','DINER'][type]});trees.push({x:gx*TILE+ROAD+8,y:gy*TILE+ROAD+8},{x:gx*TILE+TILE-10,y:gy*TILE+ROAD+8},{x:gx*TILE+ROAD+8,y:gy*TILE+TILE-10},{x:gx*TILE+TILE-10,y:gy*TILE+TILE-10});if(Math.random()<.78)for(let j=0;j<2;j++){const h=Math.random()<.5,lane=h?gy*TILE+rand(20,ROAD-20):gx*TILE+rand(20,ROAD-20);cars.push({x:h?gx*TILE+rand(ROAD+12,TILE-50):lane,y:h?lane:gy*TILE+rand(ROAD+12,TILE-50),dir:h?0:Math.PI/2,color:colors[Math.floor(Math.random()*colors.length)],speed:0,parked:true,police:false})}}
const spots=[{x:151,y:145},{x:WORLD-155,y:155},{x:WORLD-155,y:WORLD-155},{x:160,y:WORLD-155},{x:WORLD/2,y:WORLD/2}];let pickup={...spots[0]},drop={...spots[1]};function toast(m){ui.toast.textContent=m;ui.toast.style.display='block';toastTimer=2.2}function setTask(){ui.task.textContent=missionStage==='pickup'?'Преузми пакет на зеленој ознаци. Избегавај полицију!':'Испоручи пакет на златној ознаци · Награда $'+(120+delivery*25)+'.'}function updateHud(){ui.cash.textContent='$ '+cash;ui.time.textContent=String(Math.floor(gameTime/60)%24).padStart(2,'0')+':'+String(Math.floor(gameTime)%60).padStart(2,'0');ui.weather.textContent=weatherIcon+' '+weather;ui.wanted.textContent='POLICE '+('★'.repeat(wanted))+('☆'.repeat(5-wanted))}
function solidAt(x,y,r=10){return x<r||y<r||x>WORLD-r||y>WORLD-r||buildings.some(b=>x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)}function move(e,dx,dy,r=10){const nx=e.x+dx;if(!solidAt(nx,e.y,r))e.x=nx;else if(e===player&&e.inCar){e.speed*=-.28;collisions++}const ny=e.y+dy;if(!solidAt(e.x,ny,r))e.y=ny;else if(e===player&&e.inCar)e.speed*=-.28;e.x=clamp(e.x,r,WORLD-r);e.y=clamp(e.y,r,WORLD-r)}function nearestCar(){return cars.filter(c=>!c.police&&dist(c,player)<54).sort((a,b)=>dist(a,player)-dist(b,player))[0]}
