(()=>{'use strict';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height,T=320,R=92,world=T*7;
const $=id=>document.getElementById(id),ui={cash:$('cash'),time:$('time'),weather:$('weather'),wanted:$('wanted'),task:$('task'),toast:$('toast'),pause:$('pause')};
const rnd=(a,b)=>a+Math.random()*(b-a),clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),keys=new Set();
let cash=250,wanted=0,clock=480,weather='SUNNY',rain=false,weatherTimer=0,toastTimer=0,paused=false,stage=0,deliveries=0,crashes=0;
const player={x:137,y:140,dir:0,inCar:null},camera={x:0,y:0},buildings=[],cars=[],trees=[],cops=[];
const carColors=['#c85b46','#d3b94e','#477e9a','#738b53','#bd7346','#9a6386','#d1d1b4'];
for(let gy=0;gy<7;gy++)for(let gx=0;gx<7;gx++){let type=(gx*3+gy*5)%7;buildings.push({x:gx*T+R+16,y:gy*T+R+16,w:T-R-32,h:T-R-32,type,name:['HOTEL','ARCADE','MARKET','GARAGE','CLUB','OFFICE','DINER'][type]});trees.push({x:gx*T+R+8,y:gy*T+R+8},{x:gx*T+T-10,y:gy*T+R+8},{x:gx*T+R+8,y:gy*T+T-10},{x:gx*T+T-10,y:gy*T+T-10});if(Math.random()<.78)for(let j=0;j<2;j++){let horiz=Math.random()<.5,lane=horiz?gy*T+rnd(18,R-18):gx*T+rnd(18,R-18);cars.push({x:horiz?gx*T+rnd(R+18,T-48):lane,y:horiz?lane:gy*T+rnd(R+18,T-48),dir:horiz?0:Math.PI/2,color:carColors[Math.floor(Math.random()*7)],speed:0,occupied:false})}}
const spots=[{x:151,y:145},{x:world-155,y:155},{x:world-155,y:world-155},{x:160,y:world-155},{x:world/2,y:world/2}];let pickup={...spots[0]},drop={...spots[1]};
function say(text){ui.toast.textContent=text;ui.toast.style.display='block';toastTimer=2.4}function setTask(){ui.task.textContent=stage===0?'Преузми пакет на зеленој ознаци. Избегавај полицију!':'Испоручи пакет на златној ознаци · Награда $'+(120+deliveries*25)+'.'}
function hud(){ui.cash.textContent='$ '+cash;ui.time.textContent=String(Math.floor(clock/60)%24).padStart(2,'0')+':'+String(Math.floor(clock)%60).padStart(2,'0');ui.weather.textContent=(rain?'🌧️ RAIN':'☀️ SUNNY');ui.wanted.textContent='POLICE '+('★'.repeat(wanted))+('☆'.repeat(5-wanted))}
function solid(x,y,r){return x<r||y<r||x>world-r||y>world-r||buildings.some(b=>x+r>b.x&&x-r<b.x+b.w&&y+r>b.y&&y-r<b.y+b.h)}
function move(e,dx,dy,r=9){let nx=e.x+dx,ny=e.y+dy;if(!solid(nx,e.y,r))e.x=nx;else if(e===player.inCar){e.speed*=-.25;crashes++}if(!solid(e.x,ny,r))e.y=ny;else if(e===player.inCar)e.speed*=-.25;e.x=clamp(e.x,r,world-r);e.y=clamp(e.y,r,world-r)}
function nearestCar(){return cars.filter(c=>!c.occupied&&distance(c,player)<53).sort((a,b)=>distance(a,player)-distance(b,player))[0]}
function complete(){if(stage===0){stage=1;say('Пакет је преузет — испоручи га!')}else{let reward=120+deliveries*25;cash+=reward;deliveries++;stage=0;pickup={...spots[(deliveries+1)%spots.length]};drop={...spots[(deliveries+2)%spots.length]};if(distance(pickup,drop)<100)drop={...spots[(deliveries+3)%spots.length]};wanted=Math.max(0,wanted-1);say('Испорука успешна! +$'+reward)}setTask();hud()}
function interact(){if(player.inCar){let c=player.inCar;c.occupied=false;player.inCar=null;player.x=clamp(c.x+Math.cos(c.dir+Math.PI/2)*25,12,world-12);player.y=clamp(c.y+Math.sin(c.dir+Math.PI/2)*25,12,world-12);c.speed=0;say('Изашао си из возила.');return}let c=nearestCar();if(c){player.inCar=c;c.occupied=true;player.dir=c.dir;wanted=Math.min(5,wanted+1);say('Возило украдено — полиција је обавештена!');return}if(distance(player,stage===0?pickup:drop)<45)complete()}
function reset(){cash=250;wanted=0;clock=480;deliveries=0;stage=0;player.x=137;player.y=140;if(player.inCar)player.inCar.occupied=false;player.inCar=null;cops.length=0;pickup={...spots[0]};drop={...spots[1]};setTask();hud();say('Нова смена почиње!')}
function keyAction(k){if(k==='e'||k==='enter')interact();if(k==='p'||k==='escape'){paused=!paused;ui.pause.style.display=paused?'grid':'none'}if(k==='r')reset()}
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(!keys.has(k))keyAction(k);keys.add(k)});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());
document.querySelectorAll('#touch [data-key]').forEach(b=>{let k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(k);b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys.delete(k)))});document.querySelector('[data-action=interact]').addEventListener('pointerdown',e=>{e.preventDefault();interact()});const down=(...k)=>k.some(x=>keys.has(x));
function spawnCop(){let a=rnd(0,Math.PI*2),r=rnd(390,600);return{x:clamp(player.x+Math.cos(a)*r,20,world-20),y:clamp(player.y+Math.sin(a)*r,20,world-20),dir:0,speed:0,police:true}}
function update(dt){if(paused)return;clock=(clock+dt*2.2)%(24*60);weatherTimer+=dt;if(weatherTimer>90){weatherTimer=0;rain=Math.random()<.38;say(rain?'Киша пада — путеви су клизави.':'Киша је престала.')}if(toastTimer>0&&(toastTimer-=dt)<=0)ui.toast.style.display='none';let up=down('w','arrowup'),dn=down('s','arrowdown'),lf=down('a','arrowleft'),rt=down('d','arrowright'),hand=down(' ');
if(player.inCar){let c=player.inCar;if(up)c.speed=Math.min(c.speed+(rain?.095:.14)*dt*60,5.3);if(dn)c.speed=Math.max(c.speed-.18*dt*60,-2.2);c.speed*=Math.pow(hand?.91:.985,dt*60);let steer=(rt?1:0)-(lf?1:0);c.dir+=steer*Math.min(Math.abs(c.speed)/3,1)*.045*dt*60*(c.speed<0?-1:1);player.dir=c.dir;move(c,Math.cos(c.dir)*c.speed*dt*60,Math.sin(c.dir)*c.speed*dt*60,15);player.x=c.x;player.y=c.y;if(Math.abs(c.speed)>.8)for(let other of cars)if(other!==c&&distance(c,other)<26){c.speed*=-.4;crashes++;if(crashes%3===0)wanted=Math.min(5,wanted+1);break}}else{let dx=(rt?1:0)-(lf?1:0),dy=(dn?1:0)-(up?1:0);if(dx||dy){let l=Math.hypot(dx,dy);dx/=l;dy/=l;player.dir=Math.atan2(dy,dx);move(player,dx*2.1*dt*60,dy*2.1*dt*60,9)}}
if(wanted){while(cops.length<wanted)cops.push(spawnCop());for(let c of cops){let d=distance(c,player),a=Math.atan2(player.y-c.y,player.x-c.x);c.dir=a;c.speed=d>30?1.25+wanted*.2:0;move(c,Math.cos(a)*c.speed*dt*60,Math.sin(a)*c.speed*dt*60,14);if(d<25){cash=Math.max(0,cash-40);wanted=Math.max(0,wanted-1);c.x=clamp(c.x-Math.cos(a)*120,20,world-20);c.y=clamp(c.y-Math.sin(a)*120,20,world-20);if(player.inCar)player.inCar.speed*=.3;say('Полиција те је зауставила: −$40')}}}
if(distance(player,stage===0?pickup:drop)<27)complete();camera.x=clamp(player.x-W/2,0,world-W);camera.y=clamp(player.y-H/2,0,world-H);hud()}

