function rr(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);c.fill()}
function roads(){ctx.fillStyle='#192327';ctx.fillRect(0,0,world,world);for(let n=0;n<7;n++){let q=n*T;ctx.fillStyle='#353b3a';ctx.fillRect(q,0,R,world);ctx.fillRect(0,q,world,R);ctx.fillStyle='#c2b97c';for(let v=8;v<world;v+=38){ctx.fillRect(q+R/2-2,v,4,19);ctx.fillRect(v,q+R/2-2,19,4)}ctx.fillStyle='#9a9e85';ctx.fillRect(q+4,0,3,world);ctx.fillRect(0,q+4,world,3);ctx.fillRect(q+R-7,0,3,world);ctx.fillRect(0,q+R-7,world,3);for(let v=20;v<world;v+=160){ctx.fillStyle='#ddd6aa';ctx.fillRect(q+12,v,10,3);ctx.fillRect(v,q+12,3,10)}}ctx.font='bold 11px monospace';for(let y=0;y<7;y++)for(let x=0;x<7;x++){ctx.fillStyle='#a1aca255';ctx.fillText(['OLD TOWN','VICE POINT','DOCKSIDE','MIDTOWN','PALM PARK','EAST END','SUNSET'][(x+y*2)%7],x*T+R+22,y*T+R+18)}}
function drawBuildings(){const pal=['#59615a','#515f63','#75634e','#626957','#6d5351','#4d5b6b','#6f705b'],sign=['#a34e43','#d2a648','#54a3a2','#9e6852','#d49a53','#547c9a','#bd594d'];for(const b of buildings){ctx.fillStyle='#101719';rr(ctx,b.x+7,b.y+9,b.w,b.h,7);ctx.fillStyle=pal[b.type];rr(ctx,b.x,b.y,b.w,b.h,7);ctx.fillStyle='#849083';ctx.fillRect(b.x+7,b.y+8,b.w-14,4);ctx.fillStyle='#252e30';rr(ctx,b.x+12,b.y+18,b.w-24,20,2);ctx.fillStyle=sign[b.type];ctx.fillRect(b.x+17,b.y+23,b.w-34,3);ctx.fillStyle='#b9b797';ctx.font='bold 10px monospace';ctx.fillText(b.name,b.x+20,b.y+33);ctx.fillStyle='#303c3c';for(let wx=b.x+18;wx<b.x+b.w-12;wx+=31){for(let wy=b.y+52;wy<b.y+b.h-15;wy+=36){ctx.fillRect(wx,wy,15,12);ctx.fillStyle='#889180';ctx.fillRect(wx+2,wy+2,3,2);ctx.fillStyle='#303c3c'}}ctx.fillStyle='#394440';ctx.fillRect(b.x+b.w/2-10,b.y+b.h-14,20,14)}}
function drawTrees(){for(const t of trees){ctx.fillStyle='#11191a';ctx.beginPath();ctx.arc(t.x+3,t.y+5,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#42634d';ctx.beginPath();ctx.arc(t.x,t.y,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#70905c';ctx.beginPath();ctx.arc(t.x-3,t.y-3,4,0,Math.PI*2);ctx.fill()}}
function drawCar(c){ctx.save();ctx.translate(c.x,c.y);ctx.rotate(c.dir);ctx.fillStyle='#101719';rr(ctx,-17,-10,38,23,5);ctx.fillStyle=c.police?'#ece7d4':c.color;rr(ctx,-19,-11,38,22,5);ctx.fillStyle='#293b40';rr(ctx,-7,-8,14,16,3);ctx.fillStyle='#b2c7bd';ctx.fillRect(9,-7,5,14);ctx.fillStyle='#e7d28d';ctx.fillRect(16,-7,2,4);ctx.fillRect(16,4,2,4);ctx.fillStyle='#202326';ctx.fillRect(-13,-13,7,3);ctx.fillRect(4,-13,7,3);ctx.fillRect(-13,10,7,3);ctx.fillRect(4,10,7,3);if(c.police){ctx.fillStyle='#d84949';ctx.fillRect(-3,-10,5,3);ctx.fillStyle='#5e99d5';ctx.fillRect(2,-10,4,3)}ctx.restore()}
function marker(p,color,label){const pulse=1+Math.sin(performance.now()/180)*.12;ctx.save();ctx.translate(p.x,p.y);ctx.globalAlpha=.3;ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,0,23*pulse,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,14*pulse,0,Math.PI*2);ctx.stroke();ctx.fillStyle=color;ctx.font='bold 10px monospace';ctx.textAlign='center';ctx.fillText(label,0,-22*pulse);ctx.restore()}
function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);ctx.rotate(player.dir);ctx.fillStyle='#151a19';rr(ctx,-7,-7,17,16,4);ctx.fillStyle='#e2c89b';ctx.beginPath();ctx.arc(2,0,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d6ab66';ctx.fillRect(-6,-5,7,10);ctx.restore()}
function minimap(){let mw=150,mh=112,x=W-mw-16,y=16,sx=mw/world,sy=mh/world;ctx.save();ctx.fillStyle='#0c1314dd';rr(ctx,x-4,y-4,mw+8,mh+8,4);ctx.fillStyle='#444b47';for(let n=0;n<7;n++){ctx.fillRect(x+n*T*sx,y,R*sx,mh);ctx.fillRect(x,y+n*T*sy,mw,R*sy)}ctx.fillStyle='#6b6957';for(const b of buildings)ctx.fillRect(x+b.x*sx,y+b.y*sy,b.w*sx,b.h*sy);markerMini(stage===0?pickup:drop,stage===0?'#62d487':'#f0c84b');ctx.fillStyle='#f3eee1';ctx.beginPath();ctx.arc(x+player.x*sx,y+player.y*sy,3,0,Math.PI*2);ctx.fill();for(const c of cops){ctx.fillStyle='#ef5454';ctx.fillRect(x+c.x*sx-1,y+c.y*sy-1,3,3)}ctx.strokeStyle='#d8d994';ctx.strokeRect(x+camera.x*sx,y+camera.y*sy,W*sx,H*sy);ctx.restore()}
function markerMini(p,color){ctx.fillStyle=color;ctx.beginPath();ctx.arc(W-16-150+p.x*150/world,16+p.y*112/world,3,0,Math.PI*2);ctx.fill()}
function draw(){ctx.clearRect(0,0,W,H);ctx.save();ctx.translate(-camera.x,-camera.y);roads();drawTrees();drawBuildings();marker(stage===0?pickup:drop,stage===0?'#62d487':'#f0c84b',stage===0?'PICKUP':'DROP');for(const c of cars)drawCar(c);for(const c of cops)drawCar(c);if(!player.inCar)drawPlayer();if(rain){ctx.fillStyle='#7594a822';for(let i=0;i<115;i++){let x=(i*97+performance.now()*.18)%W,y=(i*53+performance.now()*.7)%H;ctx.fillRect(camera.x+x,camera.y+y,1,7)}}ctx.restore();minimap();if(player.inCar&&Math.abs(player.inCar.speed)>3){ctx.fillStyle='#d8d994';ctx.font='bold 12px monospace';ctx.fillText('SPEED '+Math.round(Math.abs(player.inCar.speed)*24)+' KM/H',16,H-18)}}
let last=performance.now();function frame(now){let dt=Math.min((now-last)/1000,.05);last=now;update(dt);draw();requestAnimationFrame(frame)}
setTask();hud();requestAnimationFrame(frame)
})();
